CREATE TABLE IF NOT EXISTS sign_audit_events (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    document_id   TEXT NOT NULL REFERENCES sign_documents(id),
    recipient_id  TEXT,
    event_type    TEXT NOT NULL,
