CREATE INDEX IF NOT EXISTS idx_sign_audit_doc ON sign_audit_events(document_id, id);

-- Append-only. The application role never gets UPDATE / DELETE on this table
-- in Postgres; SQLite has no grants, so the triggers do the same job.
CREATE TRIGGER IF NOT EXISTS sign_audit_no_update
BEFORE UPDATE ON sign_audit_events
BEGIN
    SELECT RAISE(ABORT, 'sign_audit_events is append-only');
END;
CREATE TRIGGER IF NOT EXISTS sign_audit_no_delete
BEFORE DELETE ON sign_audit_events
BEGIN
    SELECT RAISE(ABORT, 'sign_audit_events is append-only');
END;

-- Resend retries webhooks, and each retry carries the same svix-id. Dedupe on
-- the provider message id so a retry does not append a second audit event, which
-- would both bloat the chain and read as a repeated delivery failure.
CREATE TABLE IF NOT EXISTS sign_webhook_seen (
    provider      TEXT NOT NULL,
    message_id    TEXT NOT NULL,
    event_type    TEXT NOT NULL,
    seen_at       TEXT NOT NULL,
    PRIMARY KEY (provider, message_id, event_type)
);

CREATE TABLE IF NOT EXISTS sign_rate_hits (
    bucket  TEXT NOT NULL,
    ts      REAL NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sign_rate_hits ON sign_rate_hits(bucket, ts);

CREATE TABLE IF NOT EXISTS sign_templates (
    template_id  TEXT PRIMARY KEY,
    version      INTEGER NOT NULL,
    is_active    INTEGER NOT NULL DEFAULT 1,
    approved_by  TEXT,
    updated_at   TEXT NOT NULL
);

-- CANDIDATE DELTA vs the SQLite original: D1 has no BEGIN IMMEDIATE, so the audit
-- chain cannot rely on a write lock to stop two appends reading the same head.
-- This index makes a second append on the same head fail; the adapter re-reads
-- the head and retries (optimistic concurrency).
CREATE UNIQUE INDEX IF NOT EXISTS uq_sign_audit_chain ON sign_audit_events(document_id, prev_hash);
